changeSet.sql:
DO $do$
DECLARE
    root_id BIGINT;
    reports_id BIGINT;
    manage_id BIGINT;
    target_role_code TEXT;
    base_meta TEXT;
BEGIN
    base_meta := '{"sectionKey":"visualization","titleKey":"sys.nav.portal.visualization","title":"数据可视化"}';

    SELECT id INTO root_id FROM portal_menu WHERE name = 'sys.nav.portal.visualization' LIMIT 1;
    IF root_id IS NULL THEN
        INSERT INTO portal_menu (
            name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted,
            created_by, created_date, last_modified_by, last_modified_date
        ) VALUES (
            'sys.nav.portal.visualization', 'visualization', NULL, 50, base_meta, NULL, 'solar:pie-chart-bold-duotone', 'GENERAL', FALSE,
            'system', now(), 'system', now()
        )
        RETURNING id INTO root_id;
    END IF;

    SELECT id INTO reports_id FROM portal_menu WHERE name = 'sys.nav.portal.visualizationReports' LIMIT 1;
    IF reports_id IS NULL THEN
        INSERT INTO portal_menu (
            name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted,
            created_by, created_date, last_modified_by, last_modified_date
        ) VALUES (
            'sys.nav.portal.visualizationReports', 'reports', '/pages/visualization/ReportsPage', 10,
            '{"sectionKey":"visualization","entryKey":"reports","titleKey":"sys.nav.portal.visualizationReports","title":"报表与大屏"}',
            root_id, 'solar:window-frame-bold-duotone', 'GENERAL', FALSE,
            'system', now(), 'system', now()
        )
        RETURNING id INTO reports_id;
    END IF;

    SELECT id INTO manage_id FROM portal_menu WHERE name = 'sys.nav.portal.visualizationReportsManage' LIMIT 1;
    IF manage_id IS NULL THEN
        INSERT INTO portal_menu (
            name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted,
            created_by, created_date, last_modified_by, last_modified_date
        ) VALUES (
            'sys.nav.portal.visualizationReportsManage', 'reports-manage', '/pages/visualization/ReportsManagePage', 20,
            '{"sectionKey":"visualization","entryKey":"reportsManage","titleKey":"sys.nav.portal.visualizationReportsManage","title":"报表链接管理"}',
            root_id, 'solar:settings-bold-duotone', 'GENERAL', FALSE,
            'system', now(), 'system', now()
        )
        RETURNING id INTO manage_id;
    END IF;

    -- Make reports menu visible to common roles (visibility table is the source of truth for portal menus).
    FOR target_role_code IN
        SELECT unnest(ARRAY[
            'ROLE_EMPLOYEE',
            'ROLE_DEPT_DATA_VIEWER','ROLE_DEPT_DATA_DEV','ROLE_DEPT_DATA_OWNER','ROLE_DEPT_LEADER',
            'ROLE_INST_DATA_VIEWER','ROLE_INST_DATA_DEV','ROLE_INST_DATA_OWNER','ROLE_INST_LEADER',
            'ROLE_ADMIN','ROLE_OP_ADMIN'
        ])
    LOOP
        INSERT INTO portal_menu_visibility (
            id, menu_id, role_code, permission_code, data_level,
            created_by, created_date, last_modified_by, last_modified_date
        )
        SELECT
            nextval('portal_menu_visibility_seq'), reports_id, target_role_code, NULL, 'INTERNAL',
            'system', now(), 'system', now()
        WHERE NOT EXISTS (
            SELECT 1 FROM portal_menu_visibility v
            WHERE v.menu_id = reports_id AND upper(v.role_code) = upper(target_role_code)
        );
    END LOOP;

    -- Restrict manage menu to institute-level privileged roles.
    FOR target_role_code IN
        SELECT unnest(ARRAY[
            'ROLE_ADMIN','ROLE_OP_ADMIN',
            'ROLE_INST_DATA_DEV','ROLE_INST_DATA_OWNER','ROLE_INST_LEADER'
        ])
    LOOP
        INSERT INTO portal_menu_visibility (
            id, menu_id, role_code, permission_code, data_level,
            created_by, created_date, last_modified_by, last_modified_date
        )
        SELECT
            nextval('portal_menu_visibility_seq'), manage_id, target_role_code, NULL, 'INTERNAL',
            'system', now(), 'system', now()
        WHERE NOT EXISTS (
            SELECT 1 FROM portal_menu_visibility v
            WHERE v.menu_id = manage_id AND upper(v.role_code) = upper(target_role_code)
        );
    END LOOP;
END;
$do$;
